 "Un móvil": "Un telefono cellulare",
 "<div style=\"text-align:center\"><b style=\"font-size:28px;color:#fcd34d\">Aplicación</b><br><span style=\"font-size:21px;color:#d9d4f2\">Avisos y calendario</span></div>": "<div style=\"text-align:center\"><b style=\"font-size:28px;color:#fcd34d\">App</b><br><span style=\"font-size:21px;color:#d9d4f2\">Avvisi e calendario</span></div>",
